def compute(vars):
    remaining = vars["v1"]
    authorized_capacity = 10.0
    if authorized_capacity == 0:
        return None
    percentage = remaining / authorized_capacity * 100
    return {
        "value": percentage,
        "trace": {
            "remaining_capacity": remaining,
            "authorized_capacity": authorized_capacity,
            "ratio": remaining / authorized_capacity,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
